//! WP-7.13: the traceability of the blueprint to this repository, checked.
//!
//! `traceability/blueprint.json` is every H2 and H3 section of the normative blueprint and every
//! finding its registers declare, generated by `scripts/blueprint-index.py` from the knowledge
//! base. `traceability/map.yaml` is this repository's answer for each:
//!
//! | Entry                | Holds                                                                         |
//! | -------------------- | ----------------------------------------------------------------------------- |
//! | a section            | `paths` that implement it and `tests` that prove it, or `informative` and why |
//! | a finding            | the `tests` that close it                                                      |
//! | a legacy-table row   | the fixture and boundary `tests` that prove the removal, or keep the alias     |
//!
//! Any entry may also carry `gaps`: what it still lacks, each with where that is decided or what
//! proves it outside a Rust test. A gap is recorded, never silent, and the report lists every one.
//!
//! A test is `path::name`: the file it is written in and its function's name. The check refuses a
//! section or finding without an entry, an entry for one the blueprint does not have, a path that
//! does not exist, a test that is not in its file, and a section that is neither traced nor
//! declared informative; nothing is left silently as prose. It writes the report it checked to
//! `target/traceability.json`. The tests it names run in the same CI, so a linked test that fails
//! fails the build: a link is never compliance on its own.

#![allow(clippy::expect_used, clippy::panic)]

use std::collections::{BTreeMap, BTreeSet};
use std::path::{Path, PathBuf};

use serde::{Deserialize, Serialize};

fn root() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("../..")
}

fn traceability() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("traceability")
}

#[derive(Debug, Deserialize)]
struct Blueprint {
    knowledge_commit: String,
    sections: Vec<Section>,
    findings: Vec<Finding>,
    #[serde(default)]
    legacy: Vec<Finding>,
}

#[derive(Debug, Deserialize)]
struct Section {
    id: String,
}

#[derive(Debug, Deserialize)]
struct Finding {
    id: String,
}

#[derive(Debug, Default, Deserialize)]
#[serde(deny_unknown_fields)]
struct Map {
    #[serde(default)]
    sections: BTreeMap<String, Entry>,
    #[serde(default)]
    findings: BTreeMap<String, Entry>,
    #[serde(default)]
    legacy: BTreeMap<String, Entry>,
}

#[derive(Debug, Default, Deserialize, Serialize)]
#[serde(deny_unknown_fields)]
struct Entry {
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    paths: Vec<String>,
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    tests: Vec<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    informative: Option<String>,
    /// What the section or finding still lacks, said rather than hidden: a recorded gap, with where
    /// it is decided (an owner decision, a deferred package) or what proves it outside a Rust test.
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    gaps: Vec<String>,
}

#[derive(Debug, Serialize)]
struct Report<'a> {
    knowledge_commit: &'a str,
    sections: usize,
    traced: usize,
    informative: usize,
    findings: usize,
    legacy: usize,
    /// Every recorded gap, by section or finding: what the exit gate still owes, in one place.
    gaps: BTreeMap<&'a str, &'a [String]>,
    entries: &'a Map,
}

impl Serialize for Map {
    fn serialize<S: serde::Serializer>(&self, serializer: S) -> Result<S::Ok, S::Error> {
        use serde::ser::SerializeStruct as _;
        let mut map = serializer.serialize_struct("Map", 3)?;
        map.serialize_field("sections", &self.sections)?;
        map.serialize_field("findings", &self.findings)?;
        map.serialize_field("legacy", &self.legacy)?;
        map.end()
    }
}

fn blueprint() -> Blueprint {
    serde_json::from_str(
        &std::fs::read_to_string(traceability().join("blueprint.json")).expect("the index"),
    )
    .expect("the index is JSON")
}

fn map_text() -> String {
    std::fs::read_to_string(traceability().join("map.yaml")).expect("the map")
}

fn map() -> Map {
    serde_norway::from_str(&map_text()).expect("the map is YAML")
}

/// The keys written twice under `sections` or `findings`: the reader keeps the last and drops the
/// first silently, so a section claimed twice is found here, in the text.
fn repeated_keys(text: &str) -> Vec<String> {
    let mut seen = BTreeSet::new();
    let mut repeated = Vec::new();
    let mut table = String::new();
    for line in text.lines() {
        if let Some(top) = line
            .strip_suffix(':')
            .filter(|top| !top.starts_with([' ', '#']))
        {
            top.clone_into(&mut table);
            continue;
        }
        let Some(key) = line
            .strip_prefix("  ")
            .filter(|rest| !rest.starts_with([' ', '#']))
            .and_then(|rest| rest.split_once(':'))
            .map(|(key, _)| key.trim().trim_matches('"'))
        else {
            continue;
        };
        if !seen.insert(format!("{table}/{key}")) {
            repeated.push(format!("{table}: {key} is written twice"));
        }
    }
    repeated
}

/// Whether `reference`, `path::name`, names a test written in that file: a function whose
/// attributes mark it as one (`#[test]`, `#[tokio::test]` and their kin), so a helper or a
/// commented-out function never stands in for a test the CI runs.
fn test_exists(
    reference: &str,
    sources: &mut BTreeMap<String, Option<String>>,
) -> Result<(), String> {
    let (path, name) = reference
        .rsplit_once("::")
        .ok_or_else(|| format!("`{reference}` is not `path::name`"))?;
    let text = sources
        .entry(path.to_owned())
        .or_insert_with(|| std::fs::read_to_string(root().join(path)).ok());
    let Some(text) = text else {
        return Err(format!("`{reference}`: no file {path}"));
    };
    let lines: Vec<&str> = text.lines().collect();
    let declarations: Vec<usize> = lines
        .iter()
        .enumerate()
        .filter(|(_, line)| {
            let line = line.trim_start();
            !line.starts_with("//")
                && [format!("fn {name}("), format!("fn {name}<")]
                    .iter()
                    .any(|needle| line.contains(needle.as_str()))
        })
        .map(|(at, _)| at)
        .collect();
    if declarations.is_empty() {
        return Err(format!("`{reference}`: no `fn {name}` in {path}"));
    }
    // The attributes and doc comments right above the declaration.
    let marked = declarations.iter().any(|at| {
        lines[..*at]
            .iter()
            .rev()
            .map(|line| line.trim())
            .take_while(|line| {
                line.starts_with("#[") || line.starts_with("///") || line.starts_with("//")
            })
            .any(|line| {
                line.starts_with("#[test]")
                    || line.starts_with("#[tokio::test")
                    || line.starts_with("#[test_case")
                    || line.starts_with("#[rstest")
            })
    });
    if marked {
        Ok(())
    } else {
        Err(format!(
            "`{reference}`: `fn {name}` in {path} is not marked a test"
        ))
    }
}

/// Every problem `map` has against `blueprint`, one sentence each.
fn problems(blueprint: &Blueprint, map: &Map) -> Vec<String> {
    let mut found = Vec::new();
    let mut sources = BTreeMap::new();
    let sections: BTreeSet<&str> = blueprint.sections.iter().map(|s| s.id.as_str()).collect();
    let findings: BTreeSet<&str> = blueprint.findings.iter().map(|f| f.id.as_str()).collect();
    for section in &sections {
        if !map.sections.contains_key(*section) {
            found.push(format!("section {section} has no entry"));
        }
    }
    for finding in &findings {
        if !map.findings.contains_key(*finding) {
            found.push(format!("finding {finding} has no entry"));
        }
    }
    for (id, entry) in &map.sections {
        if !sections.contains(id.as_str()) {
            found.push(format!(
                "{id}: no such section in the blueprint (a dangling anchor)"
            ));
        }
        match (
            &entry.informative,
            entry.paths.is_empty(),
            entry.tests.is_empty(),
        ) {
            (Some(why), true, true) if !why.trim().is_empty() => {}
            (Some(_), _, _) => {
                found.push(format!("{id}: informative takes a reason and nothing else"))
            }
            (None, false, false) => {}
            (None, _, _) => found.push(format!(
                "{id}: traced by at least one path and one test, or declared informative"
            )),
        }
        for path in &entry.paths {
            if !root().join(path).exists() {
                found.push(format!("{id}: no path {path}"));
            }
        }
        if entry.gaps.iter().any(|gap| gap.trim().is_empty()) {
            found.push(format!("{id}: a recorded gap says what is missing"));
        }
        for test in &entry.tests {
            if let Err(why) = test_exists(test, &mut sources) {
                found.push(format!("{id}: {why}"));
            }
        }
    }
    for (id, entry) in &map.findings {
        if !findings.contains(id.as_str()) {
            found.push(format!("{id}: no such finding in the registers"));
        }
        if entry.tests.is_empty() || entry.informative.is_some() || !entry.paths.is_empty() {
            found.push(format!(
                "{id}: a finding is closed by its named tests, and only by them"
            ));
        }
        for test in &entry.tests {
            if let Err(why) = test_exists(test, &mut sources) {
                found.push(format!("{id}: {why}"));
            }
        }
    }
    // The legacy table: each removed path proven by its fixture and boundary tests, each kept alias
    // by the tests that keep it.
    let legacy: BTreeSet<&str> = blueprint.legacy.iter().map(|l| l.id.as_str()).collect();
    for row in &legacy {
        if !map.legacy.contains_key(*row) {
            found.push(format!("legacy row {row} has no entry"));
        }
    }
    for (id, entry) in &map.legacy {
        if !legacy.contains(id.as_str()) {
            found.push(format!("legacy {id}: no such row in the legacy table"));
        }
        if entry.tests.is_empty() || entry.informative.is_some() {
            found.push(format!(
                "legacy {id}: a legacy row is proven by its fixture and boundary tests"
            ));
        }
        for path in &entry.paths {
            if !root().join(path).exists() {
                found.push(format!("legacy {id}: no path {path}"));
            }
        }
        for test in &entry.tests {
            if let Err(why) = test_exists(test, &mut sources) {
                found.push(format!("legacy {id}: {why}"));
            }
        }
    }
    found
}

#[test]
fn every_section_and_finding_of_the_blueprint_is_traced_to_code_and_tests() {
    let blueprint = blueprint();
    let map = map();
    let mut found = repeated_keys(&map_text());
    found.extend(problems(&blueprint, &map));
    let informative = map
        .sections
        .values()
        .filter(|entry| entry.informative.is_some())
        .count();
    let report = Report {
        knowledge_commit: &blueprint.knowledge_commit,
        sections: blueprint.sections.len(),
        traced: map.sections.len() - informative,
        informative,
        findings: map.findings.len(),
        legacy: map.legacy.len(),
        gaps: map
            .sections
            .iter()
            .chain(&map.findings)
            .chain(&map.legacy)
            .filter(|(_, entry)| !entry.gaps.is_empty())
            .map(|(id, entry)| (id.as_str(), entry.gaps.as_slice()))
            .collect(),
        entries: &map,
    };
    let target = root().join("target");
    let _ = std::fs::create_dir_all(&target);
    let _ = std::fs::write(
        target.join("traceability.json"),
        serde_json::to_string_pretty(&report).expect("the report serializes"),
    );
    assert!(
        found.is_empty(),
        "{} traceability problems:\n{}",
        found.len(),
        found.join("\n")
    );
}

/// The check finds each problem it claims to: a check that passes because it looks for nothing
/// proves nothing.
#[test]
fn the_check_refuses_every_kind_of_gap() {
    let blueprint = Blueprint {
        knowledge_commit: String::new(),
        sections: vec![
            Section {
                id: "a.md#one".to_owned(),
            },
            Section {
                id: "a.md#two".to_owned(),
            },
            Section {
                id: "a.md#three".to_owned(),
            },
        ],
        findings: vec![Finding {
            id: "F-01".to_owned(),
        }],
        legacy: vec![Finding {
            id: "old-path".to_owned(),
        }],
    };
    let entry = |paths: &[&str], tests: &[&str], informative: Option<&str>| Entry {
        paths: paths.iter().map(|p| (*p).to_owned()).collect(),
        tests: tests.iter().map(|t| (*t).to_owned()).collect(),
        informative: informative.map(str::to_owned),
        gaps: Vec::new(),
    };
    let this = "crates/permguard-conformance/tests/traceability.rs";
    let good = format!("{this}::the_check_refuses_every_kind_of_gap");
    let map = Map {
        sections: BTreeMap::from([
            ("a.md#one".to_owned(), entry(&[this], &[&good], None)),
            ("a.md#two".to_owned(), entry(&[], &[], Some("a summary"))),
            (
                "a.md#gone".to_owned(),
                entry(&["no/such/path"], &[&format!("{this}::no_such_test")], None),
            ),
            (
                "a.md#mixed".to_owned(),
                entry(&[this], &[], Some("a summary")),
            ),
            ("a.md#untested".to_owned(), entry(&[this], &[], None)),
            (
                "a.md#helper".to_owned(),
                entry(&[this], &[&format!("{this}::root")], None),
            ),
            (
                "a.md#silent".to_owned(),
                Entry {
                    gaps: vec![" ".to_owned()],
                    ..entry(&[this], &[&good], None)
                },
            ),
        ]),
        findings: BTreeMap::from([("F-99".to_owned(), entry(&[], &[], None))]),
        legacy: BTreeMap::from([("gone-path".to_owned(), entry(&[], &[], Some("kept")))]),
    };
    let found = problems(&blueprint, &map).join("\n");
    for expected in [
        "section a.md#three has no entry",
        "finding F-01 has no entry",
        "a.md#gone: no such section",
        "a.md#gone: no path no/such/path",
        "no `fn no_such_test`",
        "F-99: no such finding",
        "F-99: a finding is closed by its named tests",
        "legacy row old-path has no entry",
        "legacy gone-path: no such row",
        "legacy gone-path: a legacy row is proven",
        "a.md#mixed: informative takes a reason and nothing else",
        "a.md#untested: traced by at least one path and one test",
        "`fn root` in crates/permguard-conformance/tests/traceability.rs is not marked a test",
        "a.md#silent: a recorded gap says what is missing",
    ] {
        assert!(
            found.contains(expected),
            "{expected} not found in:\n{found}"
        );
    }
    assert!(!found.contains("a.md#one"), "{found}");
    assert!(!found.contains("a.md#two"), "{found}");
    // A key written twice is found, though the reader would keep only the last.
    assert_eq!(
        repeated_keys(
            "sections:\n  a.md#one:\n    informative: x\n  \"a.md#one\":\n    informative: y\nfindings:\n  F-01:\n    tests: []\n"
        ),
        ["sections: a.md#one is written twice"]
    );
}
